export default function Breadcrumb({ items }: { items: any }) {
  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      {
        "@type": "ListItem",
        position: 1,
        item: { "@id": "https://travelshopbooking.com", name: "Home" },
      },
      items.map((item: any, index: number) => {
        return {
          "@type": "ListItem",
          position: index + 2,
          item: {
            "@id": "https://travelshopbooking.com" + item.pageUrl,
            name: item.pageTitle,
          },
        };
      }),
    ],
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />
      <nav
        aria-label="breadcrumb"
        className="tw-mb-4"
        style={{
          overflowX: "auto",
          whiteSpace: "nowrap",
          scrollbarWidth: "none",
        }}
      >
        <ol
          className="tw-flex tw-items-center tw-gap-2 tw-list-none tw-m-0 tw-p-0"
          style={{ fontSize: 13, width: "max-content" }}
        >
          <li>
            <a
              href="/"
              title="TravelShop Booking"
              className="tw-no-underline tw-text-[#212529] hover:tw-underline"
            >
              Home
            </a>
          </li>
          {items.map((item: any, i: number, row: any) => {
            const isLast = i + 1 === row.length;
            return (
              <li
                key={i}
                className="tw-flex tw-items-center tw-gap-2"
                aria-current={isLast ? "page" : undefined}
              >
                <span className="tw-text-[#6c757d]" aria-hidden="true">
                  /
                </span>
                {item.pageUrl && !isLast ? (
                  <a
                    href={item.pageUrl}
                    title={item.pageTitle}
                    className="tw-no-underline tw-text-[#212529] hover:tw-underline"
                  >
                    {item.pageTitle}
                  </a>
                ) : (
                  <span className="tw-text-[#6c757d]">{item.pageTitle}</span>
                )}
              </li>
            );
          })}
        </ol>
      </nav>
    </>
  );
}
